        self.assertTrue(
            all(
                cell == {
                    "suppressed": True,
                    "unique_participant_count": 2,
                    "value": None,
                }
                for cell in (
                    list(scenario["buckets"].values())
                    + list(scenario["scalars"].values())
                )
            )
        )
        self.assertIsNone(
            aggregate["partitions"]["full_corpus"]["metric_families"][
                "timing"
            ]["contribution"]
        )

