    def test_validator_is_pure_and_performs_no_filesystem_or_material_access(
        self,
    ) -> None:
        from scripts import run_emotion_state_002_phase_b as runner

        denied = AssertionError("validator touched a filesystem surface")
        with ExitStack() as stack:
            stack.enter_context(patch("builtins.open", side_effect=denied))
            for method in (
                "open",
                "read_bytes",
                "read_text",
                "stat",
                "lstat",
                "resolve",
                "exists",
                "is_file",
                "is_dir",
                "iterdir",
                "glob",
                "rglob",
            ):
                stack.enter_context(
                    patch.object(Path, method, side_effect=denied)
                )
            for method in (
                "open",
                "stat",
                "lstat",
                "scandir",
                "listdir",
                "walk",
            ):
                stack.enter_context(
                    patch.object(os, method, side_effect=denied)
                )
            for helper in (
                "_read_file_nofollow",
                "_read_verified_public_bytes",
                "_sha256_file",
                "_sha256_descriptor",
            ):
                stack.enter_context(
                    patch.object(runner, helper, side_effect=denied)
                )
            authority = self.pipeline.validate_tracked_public_evidence(
                self.evidence
            )
        self.assertEqual(len(authority.crema_audio), 7441)

    def test_resealed_manifests_reject_profile_key_type_and_identity_drift(
        self,
    ) -> None:
        frozen_profile_fields = (
            "canonical_source_url",
            "release_or_version",
            "terms_or_license",
            "access_restrictions",
            "source_labels",
            "excluded_labels",
            "language",
            "domain",
            "domain_limitations",
            "permitted_research_lanes",
            "redistribution_status",
            "manifest_version",
            "selected_artifacts",
            "source_revision",
            "release_published_at",
            "dependency_keys",
            "quality_rules",
            "known_issues",
            "runtime_influence_allowed",
        )

        def drift_value(value: Any) -> Any:
            if type(value) is bool:
                return 1
            if type(value) is int:
                return True
            if type(value) is str:
                return value + "-drift"
            if value is None:
                return "drift"
            if type(value) is list:
                return {"drift": True}
            if type(value) is dict:
                return ["drift"]
            raise AssertionError(f"unsupported manifest fixture value: {value!r}")

        names = (
            "crema-d-v1.0-audio-wav.manifest.json",
            "ami-manual-annotations-v1.6.2.manifest.json",
        )
        for name in names:
            payload = json.loads(self.evidence[name])
            for field in tuple(payload):
                def delete_field(
                    candidate: dict[str, Any],
                    key: str = field,
                ) -> None:
                    candidate.pop(key)

                with self.subTest(name=name, deleted=field):
                    self._assert_resealed_rejected(name, delete_field)

            for field in frozen_profile_fields:
                def mutate_frozen_value(
                    candidate: dict[str, Any],
                    key: str = field,
                ) -> None:
                    candidate[key] = drift_value(candidate[key])

                with self.subTest(name=name, frozen_value=field):
                    self._assert_resealed_rejected(
                        name,
                        mutate_frozen_value,
                    )

            profile_cases = (
                ("dataset_id", "future-dataset"),
                ("completion_status", True),
                ("accessed_on", True),
                ("source_label", "private"),
                ("project_label_mapping", {"future": "drift"}),
            )
            for field, value in profile_cases:
                def mutate_profile_value(
                    candidate: dict[str, Any],
                    key: str = field,
                    replacement: Any = value,
                ) -> None:
                    candidate[key] = replacement

                with self.subTest(name=name, profile_value=field):
                    self._assert_resealed_rejected(
                        name,
                        mutate_profile_value,
                    )

            for parent in (
                "local_file_hashes",
                "hash_inventory",
                "exclusion_inventory",
            ):
                for nested_field in tuple(payload[parent]):
                    def delete_nested_field(
                        candidate: dict[str, Any],
                        container: str = parent,
                        key: str = nested_field,
                    ) -> None:
                        candidate[container].pop(key)

                    with self.subTest(
                        name=name,
                        parent=parent,
                        deleted=nested_field,
                    ):
                        self._assert_resealed_rejected(
                            name,
                            delete_nested_field,
                        )

                def add_nested_field(
                    candidate: dict[str, Any],
                    container: str = parent,
                ) -> None:
                    candidate[container]["future"] = "drift"

                def replace_nested_object(
                    candidate: dict[str, Any],
                    container: str = parent,
                ) -> None:
                    candidate[container] = ["drift"]

                with self.subTest(name=name, parent=parent, added="future"):
                    self._assert_resealed_rejected(name, add_nested_field)
                with self.subTest(name=name, parent=parent, type="list"):
                    self._assert_resealed_rejected(
                        name,
                        replace_nested_object,
                    )

            nested_cases = (
                ("local_file_hashes", "inventory_sha256", "0" * 64),
                ("local_file_hashes", "selected_file_count", True),
                ("local_file_hashes", "selected_byte_count", -1),
                ("hash_inventory", "inventory_sha256", "0" * 64),
                ("hash_inventory", "selected_file_count", True),
                ("hash_inventory", "selected_byte_count", -1),
                (
                    "exclusion_inventory",
                    "quality_inventory_sha256",
                    "0" * 64,
                ),
                ("exclusion_inventory", "included_file_count", True),
                ("exclusion_inventory", "excluded_file_count", -1),
            )
            for parent, field, value in nested_cases:
                def mutate_nested(
                    candidate: dict[str, Any],
                    container: str = parent,
                    key: str = field,
                    replacement: Any = value,
                ) -> None:
                    candidate[container][key] = replacement

                with self.subTest(
                    name=name,
                    parent=parent,
                    field=field,
                ):
                    self._assert_resealed_rejected(name, mutate_nested)

